<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Days Between Dates Calculator','description'=>'Find the exact number of days between two dates.','url'=>'https://smarttoolz.in/tools/days-between-dates/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Days Between Dates</h1><p>Calculate the number of days between two dates.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Start<input id="a" type="date"></label><label>End<input id="b" type="date"></label><button id="go" class="tool-btn">Calculate</button><p id="o"></p></div></section></main><script>let d=new Date();a.value=d.toISOString().slice(0,10);b.value=new Date(d.getTime()+86400000*30).toISOString().slice(0,10);go.onclick=()=>{let x=new Date(a.value),y=new Date(b.value);o.textContent=x<=y?`${Math.round((y-x)/86400000)} days`:'End date must be after start date.'}</script><?php smarttoolz_tool_page_end(); ?>